import java.util.*;

class Solution {
    public int[] findOriginalArray(int[] changed) {
        if ((changed.length & 1) == 1) {
            return new int[0];
        }
        Map<Integer, Integer> count = new HashMap<>();
        for (int value : changed) {
            count.put(value, count.getOrDefault(value, 0) + 1);
        }

        int[] values = changed.clone();
        Arrays.sort(values);
        int[] original = new int[changed.length / 2];
        int size = 0;
        for (int x : values) {
            int remaining = count.getOrDefault(x, 0);
            if (remaining == 0) {
                continue;
            }
            count.put(x, remaining - 1);
            int doubled = x * 2;
            int doubledCount = count.getOrDefault(doubled, 0);
            if (doubledCount == 0) {
                return new int[0];
            }
            count.put(doubled, doubledCount - 1);
            original[size++] = x;
        }
        return size == original.length ? original : new int[0];
    }
}

class Solution {
    public int[] findOriginalArray(int[] changed) {
        if ((changed.length & 1) == 1) {
            return new int[0];
        }
        int max = 0;
        for (int value : changed) {
            max = Math.max(max, value);
        }
        int[] count = new int[max + 1];
        for (int value : changed) {
            count[value]++;
        }

        int[] original = new int[changed.length / 2];
        int size = 0;
        if (count[0] % 2 == 1) {
            return new int[0];
        }
        for (int i = 0; i < count[0] / 2; i++) {
            original[size++] = 0;
        }
        count[0] = 0;

        for (int x = 1; x <= max; x++) {
            while (count[x] > 0) {
                count[x]--;
                int doubled = x * 2;
                if (doubled > max || count[doubled] == 0) {
                    return new int[0];
                }
                count[doubled]--;
                original[size++] = x;
            }
        }
        return size == original.length ? original : new int[0];
    }
}

