class Solution {
    public int[] findOriginalArray(int[] changed) {
        if ((changed.length & 1) == 1) {
            return new int[0];
        }
        int[] values = changed.clone();
        Arrays.sort(values);
        ArrayDeque<Integer> neededDoubles = new ArrayDeque<>();
        int[] original = new int[changed.length / 2];
        int size = 0;

        for (int value : values) {
            if (!neededDoubles.isEmpty() && neededDoubles.peek() == value) {
                neededDoubles.poll();
            } else if (!neededDoubles.isEmpty() && neededDoubles.peek() < value) {
                return new int[0];
            } else {
                if (size == original.length) {
                    return new int[0];
                }
                original[size++] = value;
                neededDoubles.offer(value * 2);
            }
        }
        return neededDoubles.isEmpty() && size == original.length ? original : new int[0];
    }
}

