class Solution {
    public int[] findOriginalArray(int[] changed) {
        if ((changed.length & 1) == 1) {
            return new int[0];
        }
        TreeMap<Integer, Integer> count = new TreeMap<>();
        for (int value : changed) {
            count.put(value, count.getOrDefault(value, 0) + 1);
        }

        int[] original = new int[changed.length / 2];
        int size = 0;
        while (!count.isEmpty()) {
            int x = count.firstKey();
            int occurrences = count.remove(x);
            if (x == 0) {
                if ((occurrences & 1) == 1) {
                    return new int[0];
                }
                for (int i = 0; i < occurrences / 2; i++) {
                    original[size++] = 0;
                }
                continue;
            }

            int doubled = x * 2;
            int doubledCount = count.getOrDefault(doubled, 0);
            if (doubledCount < occurrences) {
                return new int[0];
            }
            for (int i = 0; i < occurrences; i++) {
                original[size++] = x;
            }
            if (doubledCount == occurrences) {
                count.remove(doubled);
            } else {
                count.put(doubled, doubledCount - occurrences);
            }
        }
        return size == original.length ? original : new int[0];
    }
}

