class Solution {
    public int[] findOriginalArray(int[] changed) {
        if ((changed.length & 1) == 1) {
            return new int[0];
        }
        int[] values = changed.clone();
        Arrays.sort(values);
        boolean[] used = new boolean[values.length];
        int[] original = new int[changed.length / 2];
        int size = 0;

        for (int i = 0; i < values.length; i++) {
            if (used[i]) {
                continue;
            }
            used[i] = true;
            int doubled = values[i] * 2;
            int match = i + 1;
            while (match < values.length && (used[match] || values[match] != doubled)) {
                match++;
            }
            if (match == values.length) {
                return new int[0];
            }
            used[match] = true;
            original[size++] = values[i];
        }
        return size == original.length ? original : new int[0];
    }
}
